//
//  Screen-Space Ambient Occlusion (SSAO)
//  Native Metal Shader - Contact Shadows
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float occlusion_strength;
    float sample_radius;
    float bias;
    float samples;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Pseudo-depth from luminance
float getDepth(float3 color) {
    return dot(color, float3(0.299, 0.587, 0.114));
}

// Random rotation for sample kernel
float2 randomRotation(float2 uv, uint frameCount) {
    float angle = fract(sin(dot(uv, float2(12.9898, 78.233))) * 43758.5453 + float(frameCount) * 0.1) * 6.28318;
    return float2(cos(angle), sin(angle));
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float4 color = sourceTexture.sample(textureSampler, in.texCoord);
    float centerDepth = getDepth(color.rgb);

    // Calculate normal from depth gradient
    float2 texelSize = 1.0 / uniforms.SourceSize.xy;
    float depthRight = getDepth(sourceTexture.sample(textureSampler, in.texCoord + float2(texelSize.x, 0.0)).rgb);
    float depthUp = getDepth(sourceTexture.sample(textureSampler, in.texCoord + float2(0.0, texelSize.y)).rgb);

    float3 normal = normalize(float3(
        centerDepth - depthRight,
        centerDepth - depthUp,
        1.0
    ));

    // Random rotation for temporal variation
    float2 randomVec = randomRotation(in.texCoord, uniforms.FrameCount);

    // Sample hemisphere around point
    float occlusion = 0.0;
    int sampleCount = int(uniforms.samples);

    for (int i = 0; i < sampleCount; i++) {
        // Generate sample position
        float angle = (float(i) / float(sampleCount)) * 6.28318;
        float radius = (float(i) / float(sampleCount)) * uniforms.sample_radius;

        // Rotate sample
        float2 offset = float2(cos(angle), sin(angle)) * radius;
        float2 rotatedOffset = float2(
            offset.x * randomVec.x - offset.y * randomVec.y,
            offset.x * randomVec.y + offset.y * randomVec.x
        );

        float2 sampleUV = in.texCoord + rotatedOffset * texelSize;

        // Sample depth
        float3 sampleColor = sourceTexture.sample(textureSampler, sampleUV).rgb;
        float sampleDepth = getDepth(sampleColor);

        // Range check
        float rangeCheck = smoothstep(0.0, 1.0, uniforms.sample_radius / abs(centerDepth - sampleDepth));

        // Accumulate occlusion
        occlusion += (sampleDepth >= centerDepth + uniforms.bias ? 1.0 : 0.0) * rangeCheck;
    }

    occlusion = 1.0 - (occlusion / float(sampleCount));

    // Apply occlusion
    float ao = pow(occlusion, uniforms.occlusion_strength);
    color.rgb *= ao;

    return color;
}

